package main

import (
	"context"
	"fmt"
	"io"
	"os"
	"os/signal"
	"strings"
	"time"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/uiform"
)

func dumpSigState(label string) {
	b, err := os.ReadFile("/proc/self/status")
	if err != nil {
		return
	}
	for _, line := range strings.Split(string(b), "\n") {
		if strings.HasPrefix(line, "Sig") || strings.HasPrefix(line, "Shd") {
			fmt.Fprintf(os.Stderr, "%s %s\n", label, line)
		}
	}
}

func main() {
	ch := make(chan os.Signal, 1)
	signal.Notify(ch, os.Interrupt)

	if mode := os.Getenv("PROBE_FORM"); mode != "" {
		var in io.Reader = strings.NewReader("\x03")
		if mode == "stdin" {
			in = os.Stdin
		}
		_, err := uiform.Confirm(context.Background(), in, os.Stderr, "Proceed?", true)
		fmt.Fprintln(os.Stderr, "form returned:", err)
	}

	dumpSigState("BEFORE-RESET")
	signal.Reset(os.Interrupt)
	dumpSigState("AFTER-RESET")

	p, _ := os.FindProcess(os.Getpid())
